  renderDragPreview?: (props: { drag: EventCalendarDragState<TData> }) => JSX.Element;
  renderMonthCell?: (props: {
    day: Date;
    segments: EventCalendarDayBucket<TData>;
    isToday: boolean;
    isOutside: boolean;
