  renderDayHeader?: (props: { day: Date; view: CalendarView; isToday: boolean }) => JSX.Element;
  renderTimeGutterSlot?: (props: { time: Date; hour: number; minute: number }) => JSX.Element;
  renderAllDaySection?: (props: {
    days: Date[];
